#!/usr/bin/env bash
set -e
mkdir -p spiderpi-sim-starter
cd spiderpi-sim-starter
python3 - <<'PY'
from pathlib import Path
files = {
'README.md': '# SpiderPi Simulator Starter\n\nLocal simulator for a Spidercam-style cable robot using React + Three.js + FastAPI.\n\n## Quick start\n\n### Backend\n```bash\ncd backend\npython3 -m venv .venv\nsource .venv/bin/activate\npip install -r requirements.txt\nuvicorn main:app --reload --port 8000\n```\n\n### Frontend\n```bash\ncd frontend\nnpm install\nnpm run dev\n```\n\nOpen http://localhost:5173\n',
'.gitignore': 'backend/.venv/\nfrontend/node_modules/\nfrontend/dist/\n__pycache__/\n*.pyc\ndata/*.yaml\n',
'backend/requirements.txt': 'fastapi==0.115.12\nuvicorn[standard]==0.34.0\npydantic==2.11.3\nPyYAML==6.0.2\n',
'backend/persistent_config.py': 'from __future__ import annotations\nfrom pydantic import BaseModel, Field\nfrom typing import Dict, List, Optional\nfrom pathlib import Path\nimport yaml, tempfile, os\n\nCONFIG_PATH = Path("data/spiderpi.yaml")\nCONFIG_PATH.parent.mkdir(parents=True, exist_ok=True)\n\nclass MotorPinConfig(BaseModel):\n    step: int\n    dir: int\n    en: Optional[int] = None\n    invert_dir: bool = False\n\nclass MotorTuning(BaseModel):\n    rated_current_a: float = 1.7\n    holding_torque_nm: float = 0.42\n    drv8825_vref: float = 0.75\n    microsteps: int = 16\n    start_freq_hz: int = 250\n    max_freq_hz: int = 2200\n    accel_steps_s2: int = 7000\n\nclass FrameConfig(BaseModel):\n    anchors: Dict[str, List[float]] = Field(default_factory=lambda: {\n        "A": [0.0, 0.0, 1.5],\n        "B": [2.0, 0.0, 1.5],\n        "C": [2.0, 2.0, 1.5],\n        "D": [0.0, 2.0, 1.5],\n    })\n    bounds: Dict[str, List[float]] = Field(default_factory=lambda: {\n        "x": [0.2, 1.8],\n        "y": [0.2, 1.8],\n        "z": [0.3, 1.3],\n    })\n    spool_radius_m: float = 0.011\n    motor_steps_per_rev: int = 200\n\nclass RigConfig(BaseModel):\n    carriage_mass_kg: float = 0.40\n    payload_mass_kg: float = 0.08\n    gravity: float = 9.81\n    cable_drag_coeff: float = 0.08\n    max_speed_mps: float = 0.7\n    max_accel_mps2: float = 0.9\n\nclass CalibrationState(BaseModel):\n    homed: Dict[str, bool] = Field(default_factory=lambda: {"A": False, "B": False, "C": False, "D": False})\n    zero_lengths_m: Dict[str, float] = Field(default_factory=lambda: {"A": 0.0, "B": 0.0, "C": 0.0, "D": 0.0})\n    line_offsets_steps: Dict[str, int] = Field(default_factory=lambda: {"A": 0, "B": 0, "C": 0, "D": 0})\n    measured_spool_radius_m: Optional[float] = None\n    motor_direction_ok: Dict[str, bool] = Field(default_factory=lambda: {"A": False, "B": False, "C": False, "D": False})\n    limits_verified: bool = False\n    notes: List[str] = Field(default_factory=list)\n\nclass SystemConfig(BaseModel):\n    frame: FrameConfig = Field(default_factory=FrameConfig)\n    rig: RigConfig = Field(default_factory=RigConfig)\n    motors: MotorTuning = Field(default_factory=MotorTuning)\n    gpio_map: Dict[str, MotorPinConfig] = Field(default_factory=lambda: {\n        "A": MotorPinConfig(step=12, dir=5, en=6),\n        "B": MotorPinConfig(step=13, dir=16, en=6),\n        "C": MotorPinConfig(step=19, dir=20, en=6),\n        "D": MotorPinConfig(step=26, dir=21, en=6),\n    })\n    limit_switches: Dict[str, int] = Field(default_factory=lambda: {\n        "A": 17,\n        "B": 27,\n        "C": 22,\n        "D": 23,\n    })\n    calibration: CalibrationState = Field(default_factory=CalibrationState)\n\nDEFAULT_CONFIG = SystemConfig()\n\ndef save_config(cfg: SystemConfig):\n    payload = yaml.safe_dump(cfg.model_dump(mode="python"), sort_keys=False)\n    with tempfile.NamedTemporaryFile("w", delete=False, dir=str(CONFIG_PATH.parent), suffix=".tmp") as tf:\n        tf.write(payload)\n        temp_name = tf.name\n    os.replace(temp_name, CONFIG_PATH)\n\ndef load_config() -> SystemConfig:\n    if not CONFIG_PATH.exists():\n        save_config(DEFAULT_CONFIG)\n        return DEFAULT_CONFIG\n    raw = yaml.safe_load(CONFIG_PATH.read_text()) or {}\n    return SystemConfig.model_validate(raw)\n',
'backend/planner.py': 'from math import cos, sin, pi\n\ndef lerp(a, b, t):\n    return a + (b - a) * t\n\ndef line_path(p0, p1, steps=60):\n    out = []\n    for i in range(steps + 1):\n        t = i / steps\n        out.append({\n            "x": lerp(p0["x"], p1["x"], t),\n            "y": lerp(p0["y"], p1["y"], t),\n            "z": lerp(p0["z"], p1["z"], t),\n        })\n    return out\n\ndef square_path(center, size=0.8, z=0.9, steps_per_edge=40):\n    cx, cy = center["x"], center["y"]\n    s = size / 2\n    pts = [\n        {"x": cx - s, "y": cy - s, "z": z},\n        {"x": cx + s, "y": cy - s, "z": z},\n        {"x": cx + s, "y": cy + s, "z": z},\n        {"x": cx - s, "y": cy + s, "z": z},\n        {"x": cx - s, "y": cy - s, "z": z},\n    ]\n    out = []\n    for i in range(len(pts) - 1):\n        seg = line_path(pts[i], pts[i + 1], steps_per_edge)\n        out.extend(seg[:-1] if i < len(pts) - 2 else seg)\n    return out\n\ndef circle_path(center, radius=0.45, z=0.9, steps=180):\n    cx, cy = center["x"], center["y"]\n    return [\n        {"x": cx + radius * cos(2 * pi * i / steps), "y": cy + radius * sin(2 * pi * i / steps), "z": z}\n        for i in range(steps + 1)\n    ]\n',
'backend/main.py': 'from __future__ import annotations\nfrom fastapi import FastAPI, WebSocket, WebSocketDisconnect\nfrom fastapi.middleware.cors import CORSMiddleware\nfrom pydantic import BaseModel\nfrom math import sqrt, pi\nimport asyncio, json, time\nfrom persistent_config import load_config\nfrom planner import square_path, circle_path\n\napp = FastAPI()\napp.add_middleware(CORSMiddleware, allow_origins=["*"], allow_credentials=True, allow_methods=["*"], allow_headers=["*"])\n\ncfg = load_config()\nanchors = cfg.frame.anchors\nbounds = cfg.frame.bounds\nspool_radius = cfg.frame.spool_radius_m\nmotor_steps_per_rev = cfg.frame.motor_steps_per_rev\nmicrosteps = cfg.motors.microsteps\n\nclass Manager:\n    def __init__(self):\n        self.clients = set()\n    async def connect(self, ws: WebSocket):\n        await ws.accept()\n        self.clients.add(ws)\n    def disconnect(self, ws: WebSocket):\n        self.clients.discard(ws)\n    async def broadcast(self, payload: dict):\n        dead = []\n        for client in list(self.clients):\n            try:\n                await client.send_text(json.dumps(payload))\n            except Exception:\n                dead.append(client)\n        for d in dead:\n            self.disconnect(d)\n\nmanager = Manager()\n\ndef lengths_from_xyz(x: float, y: float, z: float):\n    out = {}\n    for name, (ax, ay, az) in anchors.items():\n        out[name] = sqrt((x-ax)**2 + (y-ay)**2 + (z-az)**2)\n    return out\n\ndef steps_from_delta_length(delta_len: float) -> int:\n    revs = delta_len / (2 * pi * spool_radius)\n    return int(revs * motor_steps_per_rev * microsteps)\n\nSTATE = {\n    "mode": "sim",\n    "status": "idle",\n    "estop": False,\n    "position": {"x": 1.0, "y": 1.0, "z": 0.9},\n    "target": {"x": 1.0, "y": 1.0, "z": 0.9},\n    "speed": 0.4,\n    "anchors": anchors,\n    "bounds": bounds,\n    "lengths": {},\n    "steps": {"A": 0, "B": 0, "C": 0, "D": 0},\n    "spools": {"A": 0.0, "B": 0.0, "C": 0.0, "D": 0.0},\n    "trail": [],\n    "path": {"name": None, "index": 0, "points": []},\n    "updated_at": time.time(),\n}\nSTATE["lengths"] = lengths_from_xyz(**STATE["position"])\n\nclass Target(BaseModel):\n    x: float\n    y: float\n    z: float\n    speed: float = 0.4\n\nclass PathCmd(BaseModel):\n    name: str\n    speed: float = 0.35\n    size: float = 0.8\n    radius: float = 0.45\n    z: float = 0.9\n\n@app.on_event("startup")\nasync def startup():\n    asyncio.create_task(sim_loop())\n    asyncio.create_task(push_loop())\n\ndef set_target(x: float, y: float, z: float, speed: float):\n    x = max(bounds["x"][0], min(bounds["x"][1], x))\n    y = max(bounds["y"][0], min(bounds["y"][1], y))\n    z = max(bounds["z"][0], min(bounds["z"][1], z))\n    STATE["target"] = {"x": x, "y": y, "z": z}\n    STATE["speed"] = max(0.05, min(speed, 1.0))\n    STATE["status"] = "moving"\n\nasync def sim_loop():\n    dt = 1/60\n    while True:\n        if not STATE["estop"]:\n            px, py, pz = STATE["position"].values()\n            tx, ty, tz = STATE["target"].values()\n            dx, dy, dz = tx-px, ty-py, tz-pz\n            dist = sqrt(dx*dx + dy*dy + dz*dz)\n            if dist < 0.003:\n                if STATE["path"]["points"]:\n                    idx = STATE["path"]["index"] + 1\n                    if idx < len(STATE["path"]["points"]):\n                        STATE["path"]["index"] = idx\n                        p = STATE["path"]["points"][idx]\n                        set_target(p["x"], p["y"], p["z"], STATE["speed"])\n                    else:\n                        STATE["path"] = {"name": None, "index": 0, "points": []}\n                        STATE["status"] = "idle"\n                else:\n                    STATE["status"] = "idle"\n            else:\n                step = STATE["speed"] * dt\n                ratio = min(1.0, step / dist)\n                nx, ny, nz = px + dx*ratio, py + dy*ratio, pz + dz*ratio\n                prev = STATE["lengths"]\n                nxt = lengths_from_xyz(nx, ny, nz)\n                for k in nxt:\n                    dl = nxt[k] - prev[k]\n                    STATE["steps"][k] += steps_from_delta_length(dl)\n                    STATE["spools"][k] += dl / spool_radius\n                STATE["position"] = {"x": nx, "y": ny, "z": nz}\n                STATE["lengths"] = nxt\n                STATE["updated_at"] = time.time()\n                STATE["trail"].append({"x": nx, "y": ny, "z": nz})\n                STATE["trail"] = STATE["trail"][-250:]\n        await asyncio.sleep(dt)\n\nasync def push_loop():\n    while True:\n        await manager.broadcast({"type": "state", **STATE})\n        await asyncio.sleep(1/20)\n\n@app.get(\'/state\')\ndef get_state():\n    return STATE\n\n@app.post(\'/move\')\ndef move(target: Target):\n    STATE["path"] = {"name": None, "index": 0, "points": []}\n    set_target(target.x, target.y, target.z, target.speed)\n    return {"ok": True}\n\n@app.post(\'/path\')\ndef run_path(cmd: PathCmd):\n    if cmd.name == \'square\':\n        pts = square_path({"x": 1.0, "y": 1.0}, size=cmd.size, z=cmd.z)\n    elif cmd.name == \'circle\':\n        pts = circle_path({"x": 1.0, "y": 1.0}, radius=cmd.radius, z=cmd.z)\n    else:\n        return {"ok": False, "error": \'unknown path\'}\n    STATE["path"] = {"name": cmd.name, "index": 0, "points": pts}\n    STATE["speed"] = cmd.speed\n    if pts:\n        set_target(pts[0]["x"], pts[0]["y"], pts[0]["z"], cmd.speed)\n    return {"ok": True, "points": len(pts)}\n\n@app.post(\'/stop\')\ndef stop():\n    STATE["path"] = {"name": None, "index": 0, "points": []}\n    STATE["target"] = dict(STATE["position"])\n    STATE["status"] = \'idle\'\n    return {"ok": True}\n\n@app.post(\'/estop\')\ndef estop():\n    STATE["estop"] = True\n    STATE["status"] = \'stopped\'\n    return {"ok": True}\n\n@app.post(\'/reset-estop\')\ndef reset_estop():\n    STATE["estop"] = False\n    STATE["status"] = \'idle\'\n    return {"ok": True}\n\n@app.websocket(\'/ws\')\nasync def ws_endpoint(ws: WebSocket):\n    await manager.connect(ws)\n    await ws.send_text(json.dumps({"type": "state", **STATE}))\n    try:\n        while True:\n            data = await ws.receive_json()\n            t = data.get(\'type\')\n            if t == \'jog\' and not STATE["estop"]:\n                px, py, pz = STATE["position"].values()\n                set_target(px + float(data.get(\'dx\', 0)), py + float(data.get(\'dy\', 0)), pz + float(data.get(\'dz\', 0)), float(data.get(\'speed\', 0.4)))\n            elif t == \'move\' and not STATE["estop"]:\n                set_target(float(data[\'x\']), float(data[\'y\']), float(data[\'z\']), float(data.get(\'speed\', 0.4)))\n            elif t == \'path\' and not STATE["estop"]:\n                name = data.get(\'name\')\n                if name == \'square\':\n                    pts = square_path({"x": 1.0, "y": 1.0}, size=float(data.get(\'size\', 0.8)), z=float(data.get(\'z\', 0.9)))\n                elif name == \'circle\':\n                    pts = circle_path({"x": 1.0, "y": 1.0}, radius=float(data.get(\'radius\', 0.45)), z=float(data.get(\'z\', 0.9)))\n                else:\n                    pts = []\n                if pts:\n                    STATE["path"] = {"name": name, "index": 0, "points": pts}\n                    STATE["speed"] = float(data.get(\'speed\', 0.35))\n                    set_target(pts[0]["x"], pts[0]["y"], pts[0]["z"], STATE["speed"])\n            elif t == \'stop\':\n                STATE["path"] = {"name": None, "index": 0, "points": []}\n                STATE["target"] = dict(STATE["position"])\n                STATE["status"] = \'idle\'\n            elif t == \'estop\':\n                STATE["estop"] = True\n                STATE["status"] = \'stopped\'\n            elif t == \'reset-estop\':\n                STATE["estop"] = False\n                STATE["status"] = \'idle\'\n    except WebSocketDisconnect:\n        manager.disconnect(ws)\n',
'frontend/package.json': '{\n  "name": "spiderpi-sim-frontend",\n  "private": true,\n  "version": "0.0.1",\n  "type": "module",\n  "scripts": {\n    "dev": "vite",\n    "build": "tsc -b && vite build",\n    "preview": "vite preview"\n  },\n  "dependencies": {\n    "@react-three/drei": "^9.122.0",\n    "@react-three/fiber": "^8.17.14",\n    "react": "^18.3.1",\n    "react-dom": "^18.3.1",\n    "three": "^0.164.1"\n  },\n  "devDependencies": {\n    "@types/react": "^18.3.12",\n    "@types/react-dom": "^18.3.1",\n    "@types/three": "^0.164.0",\n    "@vitejs/plugin-react": "^4.3.3",\n    "typescript": "^5.6.3",\n    "vite": "^5.4.10"\n  }\n}',
'frontend/tsconfig.json': '{\n  "compilerOptions": {\n    "target": "ES2020",\n    "useDefineForClassFields": true,\n    "lib": [\n      "ES2020",\n      "DOM",\n      "DOM.Iterable"\n    ],\n    "skipLibCheck": true,\n    "esModuleInterop": true,\n    "allowSyntheticDefaultImports": true,\n    "strict": true,\n    "forceConsistentCasingInFileNames": true,\n    "module": "ESNext",\n    "moduleResolution": "Node",\n    "resolveJsonModule": true,\n    "isolatedModules": true,\n    "noEmit": true,\n    "jsx": "react-jsx"\n  },\n  "include": [\n    "src"\n  ]\n}',
'frontend/vite.config.ts': 'import { defineConfig } from "vite";\nimport react from "@vitejs/plugin-react";\nexport default defineConfig({ plugins: [react()] });\n',
'frontend/index.html': '<!doctype html>\n<html lang="en">\n  <head>\n    <meta charset="UTF-8" />\n    <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n    <title>SpiderPi Simulator</title>\n  </head>\n  <body>\n    <div id="root"></div>\n    <script type="module" src="/src/main.tsx"></script>\n  </body>\n</html>\n',
'frontend/src/main.tsx': 'import React from "react";\nimport ReactDOM from "react-dom/client";\nimport App from "./App";\nimport "./styles.css";\nReactDOM.createRoot(document.getElementById("root")!).render(\n  <React.StrictMode><App /></React.StrictMode>\n);\n',
'frontend/src/types.ts': 'export type Vec3 = { x: number; y: number; z: number };\nexport type AnchorMap = Record<string, [number, number, number]>;\nexport type SpiderState = {\n  mode: string;\n  status: string;\n  estop: boolean;\n  position: Vec3;\n  target: Vec3;\n  speed: number;\n  anchors: AnchorMap;\n  bounds: { x: [number, number]; y: [number, number]; z: [number, number] };\n  lengths: Record<string, number>;\n  steps: Record<string, number>;\n  spools: Record<string, number>;\n  trail: Vec3[];\n  path: { name: string | null; index: number; points: Vec3[] };\n  updated_at: number;\n};\n',
'frontend/src/hooks/useSpiderSocket.ts': 'import { useEffect, useRef, useState } from "react";\nimport { SpiderState } from "../types";\nconst WS_URL = "ws://127.0.0.1:8000/ws";\nconst HTTP_URL = "http://127.0.0.1:8000";\nexport function useSpiderSocket() {\n  const [state, setState] = useState<SpiderState | null>(null);\n  const [connected, setConnected] = useState(false);\n  const wsRef = useRef<WebSocket | null>(null);\n  const retryRef = useRef<number | null>(null);\n  const connect = () => {\n    const ws = new WebSocket(WS_URL);\n    wsRef.current = ws;\n    ws.onopen = () => setConnected(true);\n    ws.onmessage = (ev) => {\n      const msg = JSON.parse(ev.data);\n      if (msg.type === "state") setState(msg);\n    };\n    ws.onclose = () => {\n      setConnected(false);\n      retryRef.current = window.setTimeout(connect, 1000);\n    };\n    ws.onerror = () => ws.close();\n  };\n  useEffect(() => {\n    fetch(`${HTTP_URL}/state`).then(r => r.json()).then(setState).catch(() => null);\n    connect();\n    return () => {\n      if (retryRef.current) window.clearTimeout(retryRef.current);\n      wsRef.current?.close();\n    };\n  }, []);\n  const send = (msg: object) => {\n    if (wsRef.current?.readyState === WebSocket.OPEN) wsRef.current.send(JSON.stringify(msg));\n  };\n  return {\n    state, connected,\n    jog: (dx: number, dy: number, dz: number, speed = 0.4) => send({ type: "jog", dx, dy, dz, speed }),\n    move: (x: number, y: number, z: number, speed = 0.4) => send({ type: "move", x, y, z, speed }),\n    runPath: (name: string, opts: Record<string, number> = {}) => send({ type: "path", name, ...opts }),\n    stop: () => send({ type: "stop" }),\n    estop: () => send({ type: "estop" }),\n    resetEstop: () => send({ type: "reset-estop" }),\n  };\n}\n',
'frontend/src/components/SpiderScene.tsx': 'import { Canvas } from "@react-three/fiber";\nimport { OrbitControls, Line, Grid, Html, Environment } from "@react-three/drei";\nimport { SpiderState } from "../types";\nimport * as THREE from "three";\n\nfunction Trail({ points }: { points: { x: number; y: number; z: number }[] }) {\n  if (!points.length) return null;\n  const pts = points.map((p) => [p.x, p.z, p.y] as [number, number, number]);\n  return <Line points={pts} color="#22c55e" lineWidth={1} dashed />;\n}\n\nexport function SpiderScene({ state }: { state: SpiderState | null }) {\n  if (!state) return <div className="sceneFallback">Loading 3D scene...</div>;\n  const A: [number, number, number] = [0, 1.5, 0];\n  const B: [number, number, number] = [2, 1.5, 0];\n  const C: [number, number, number] = [2, 1.5, 2];\n  const D: [number, number, number] = [0, 1.5, 2];\n  const P: [number, number, number] = [state.position.x, state.position.z, state.position.y];\n  return (\n    <div className="sceneWrap">\n      <Canvas shadows camera={{ position: [3.1, 2.4, 3.1], fov: 45 }}>\n        <color attach="background" args={["#0b1020"]} />\n        <ambientLight intensity={0.8} />\n        <directionalLight position={[3, 4, 2]} intensity={1.6} castShadow />\n        <Grid args={[4, 4]} position={[1, 0, 1]} cellColor={"#334155"} sectionColor={"#475569"} />\n        <Line points={[A, B, C, D, A]} color="#64748b" lineWidth={2} />\n        <Line points={[A, P]} color="#ef4444" lineWidth={2} />\n        <Line points={[B, P]} color="#ef4444" lineWidth={2} />\n        <Line points={[C, P]} color="#ef4444" lineWidth={2} />\n        <Line points={[D, P]} color="#ef4444" lineWidth={2} />\n        <Trail points={state.trail} />\n        {[A, B, C, D].map((pos, i) => (\n          <mesh key={i} position={pos}><boxGeometry args={[0.08,0.08,0.08]} /><meshStandardMaterial color="#38bdf8" /></mesh>\n        ))}\n        <mesh position={P}><sphereGeometry args={[0.06, 24, 24]} /><meshStandardMaterial color={state.estop ? "#dc2626" : "#f59e0b"} /></mesh>\n        <mesh position={[P[0], P[1]-0.05, P[2]]}><boxGeometry args={[0.22,0.04,0.12]} /><meshStandardMaterial color="#f8fafc" /></mesh>\n        <Html position={[P[0], P[1]+0.16, P[2]]} center distanceFactor={10}><div className="tele3d">X {state.position.x.toFixed(2)} Y {state.position.y.toFixed(2)} Z {state.position.z.toFixed(2)}</div></Html>\n        <OrbitControls makeDefault target={new THREE.Vector3(1, 0.8, 1)} />\n        <Environment preset="city" />\n      </Canvas>\n    </div>\n  );\n}\n',
'frontend/src/components/Controls.tsx': 'import { SpiderState } from "../types";\nexport function Controls({ state, jog, runPath, stop, estop, resetEstop }:{\n  state: SpiderState | null;\n  jog: (dx:number,dy:number,dz:number,speed?:number)=>void;\n  runPath: (name:string, opts?:Record<string,number>)=>void;\n  stop: ()=>void;\n  estop: ()=>void;\n  resetEstop: ()=>void;\n}) {\n  if (!state) return <div className="panel">Loading controls...</div>;\n  return (\n    <div className="panel">\n      <h3>Controls</h3>\n      <div className="grid2">\n        <button onClick={() => jog(0,-0.1,0)}>Forward</button>\n        <button onClick={() => jog(0,0.1,0)}>Back</button>\n        <button onClick={() => jog(-0.1,0,0)}>Left</button>\n        <button onClick={() => jog(0.1,0,0)}>Right</button>\n        <button onClick={() => jog(0,0,0.08)}>Down</button>\n        <button onClick={() => jog(0,0,-0.08)}>Up</button>\n      </div>\n      <div className="grid2">\n        <button onClick={() => runPath(\'square\', { size:0.8, z:state.target.z, speed:0.35 })}>Square</button>\n        <button onClick={() => runPath(\'circle\', { radius:0.45, z:state.target.z, speed:0.35 })}>Circle</button>\n      </div>\n      <div className="grid2">\n        <button onClick={stop}>Stop</button>\n        <button className="danger" onClick={estop}>E-STOP</button>\n      </div>\n      <button className="warn" onClick={resetEstop}>Reset E-Stop</button>\n    </div>\n  );\n}\n',
'frontend/src/components/Telemetry.tsx': 'import { SpiderState } from "../types";\nexport function Telemetry({ state, connected }:{ state: SpiderState | null; connected:boolean }) {\n  if (!state) return <div className="panel">Loading state...</div>;\n  return <div className="panel">\n    <h3>Telemetry</h3>\n    <div className="kv"><span>WS</span><span>{connected ? \'Connected\' : \'Disconnected\'}</span></div>\n    <div className="kv"><span>Status</span><span>{state.status}</span></div>\n    <div className="kv"><span>X</span><span>{state.position.x.toFixed(3)} m</span></div>\n    <div className="kv"><span>Y</span><span>{state.position.y.toFixed(3)} m</span></div>\n    <div className="kv"><span>Z</span><span>{state.position.z.toFixed(3)} m</span></div>\n    <div className="kv"><span>Len A</span><span>{state.lengths.A?.toFixed(3)} m</span></div>\n    <div className="kv"><span>Len B</span><span>{state.lengths.B?.toFixed(3)} m</span></div>\n    <div className="kv"><span>Len C</span><span>{state.lengths.C?.toFixed(3)} m</span></div>\n    <div className="kv"><span>Len D</span><span>{state.lengths.D?.toFixed(3)} m</span></div>\n  </div>;\n}\n',
'frontend/src/components/TopMap.tsx': 'import { SpiderState } from "../types";\nexport function TopMap({ state }:{ state: SpiderState | null }) {\n  if (!state) return <div className="panel">Loading map...</div>;\n  const width = 280, height = 280;\n  const [xmin, xmax] = state.bounds.x;\n  const [ymin, ymax] = state.bounds.y;\n  const xToPx = (x:number) => ((x-xmin)/(xmax-xmin))*width;\n  const yToPx = (y:number) => ((y-ymin)/(ymax-ymin))*height;\n  return <div className="panel"><h3>XY Map</h3><svg width={width} height={height} className="map"><rect x="0" y="0" width={width} height={height} fill="#121826" rx="10" /><circle cx={xToPx(state.position.x)} cy={yToPx(state.position.y)} r="8" fill="#f59e0b" /></svg></div>;\n}\n',
'frontend/src/App.tsx': 'import { useSpiderSocket } from "./hooks/useSpiderSocket";\nimport { SpiderScene } from "./components/SpiderScene";\nimport { Controls } from "./components/Controls";\nimport { Telemetry } from "./components/Telemetry";\nimport { TopMap } from "./components/TopMap";\n\nexport default function App() {\n  const { state, connected, jog, runPath, stop, estop, resetEstop } = useSpiderSocket();\n  return (\n    <div className="app">\n      <header className="topbar">\n        <div>\n          <h1>SpiderPi Simulator</h1>\n          <p>MacBook starter project for React + Three.js + FastAPI</p>\n        </div>\n        <div className={`pill ${connected ? "ok" : "bad"}`}>{connected ? "WS Connected" : "WS Disconnected"}</div>\n      </header>\n      <main className="layout">\n        <section className="left"><SpiderScene state={state} /></section>\n        <section className="right">\n          <Controls state={state} jog={jog} runPath={runPath} stop={stop} estop={estop} resetEstop={resetEstop} />\n          <TopMap state={state} />\n          <Telemetry state={state} connected={connected} />\n        </section>\n      </main>\n    </div>\n  );\n}\n',
'frontend/src/styles.css': ' :root { font-family: Inter, system-ui, Arial, sans-serif; color: #e5e7eb; background: #0f172a; }\n* { box-sizing: border-box; }\nbody, html, #root { margin: 0; width: 100%; height: 100%; }\nbody { background: linear-gradient(180deg, #0b1020 0%, #101827 100%); }\n.app { min-height: 100vh; padding: 16px; }\n.topbar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; }\n.topbar h1 { margin: 0 0 4px; font-size: 28px; }\n.topbar p { margin: 0; color: #94a3b8; }\n.layout { display: grid; grid-template-columns: 1.6fr 0.9fr; gap: 16px; }\n.right { display: grid; gap: 16px; align-content: start; }\n.sceneWrap { height: 78vh; border-radius: 16px; overflow: hidden; border: 1px solid rgba(148, 163, 184, 0.16); background: #0b1020; }\n.sceneFallback { display: grid; place-items: center; height: 78vh; border-radius: 16px; background: #0b1020; }\n.panel { background: rgba(15, 23, 42, 0.92); border: 1px solid rgba(148, 163, 184, 0.16); border-radius: 16px; padding: 16px; }\n.panel h3 { margin-top: 0; }\n.grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin: 12px 0; }\nbutton { background: #1e293b; color: #e2e8f0; border: 1px solid #334155; border-radius: 10px; padding: 10px 12px; cursor: pointer; }\nbutton.danger { background: #7f1d1d; border-color: #ef4444; }\nbutton.warn { background: #78350f; border-color: #f59e0b; }\n.kv { display: flex; justify-content: space-between; border-bottom: 1px solid rgba(148, 163, 184, 0.12); padding: 6px 0; }\n.map { display: block; margin: 8px auto; }\n.pill { padding: 8px 12px; border-radius: 999px; font-size: 14px; border: 1px solid; }\n.pill.ok { color: #86efac; border-color: #15803d; background: rgba(22, 101, 52, 0.25); }\n.pill.bad { color: #fca5a5; border-color: #b91c1c; background: rgba(127, 29, 29, 0.25); }\n.tele3d { background: rgba(15, 23, 42, 0.9); border: 1px solid #334155; border-radius: 10px; padding: 6px 8px; color: #fff; font-size: 12px; }\n',
}
for rel, content in files.items():
